function schemaError(schema, value, root, path) {
    return Runtime.ProtocolValidation.schemaError(schema, value, root, path);
}

function eventError(envelope) {
    return Runtime.ProtocolValidation.validateEvent(eventContracts, envelope);
}

function requestError(method, params) {
    return Runtime.ProtocolValidation.validateRequest(contracts, method, params);
}

function responseError(method, envelope) {
    return Runtime.ProtocolValidation.validateResponse(contracts, method, envelope);
}
